const getGalleryUsage = `-- name: GetGalleryUsage :one
SELECT
    count(*)::INT4 AS image_count,
    COALESCE(sum(byte_size), 0)::INT8 AS byte_count
FROM gallery_images
WHERE campaign_id = $1
`

type GetGalleryUsageRow struct {
	ImageCount int32
	ByteCount  int64
}

// How much of the quota the campaign uses: its images and their bytes.
// Upload reads it inside the transaction that inserts the new row, so two
// uploads racing cannot both squeeze under the limit: CockroachDB's
// SERIALIZABLE isolation makes one of them retry and count again.
func (q *Queries) GetGalleryUsage(ctx context.Context, campaignID string) (GetGalleryUsageRow, error) {
	row := q.db.QueryRow(ctx, getGalleryUsage, campaignID)
	var i GetGalleryUsageRow
	err := row.Scan(&i.ImageCount, &i.ByteCount)
	return i, err
}

